import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 회계기간은 closing_data.closing_period와 같은 YYYY-MM 형식이다.
const PERIOD_PATTERN = /^\d{4}-(0[1-9]|1[0-2])$/;
// 가정: 재무제표 종류는 화면 목록의 이름만 받는다. 종류별 계정 범위 규칙이 입력에 없어 종류는 검증만 한다.
const STATEMENT_TYPES = [
  '합계잔액시산표',
  '원가보고서',
  '손익계산서',
  '이익잉여금처분계산서',
  '재무상태표',
  '자본변동표',
  '현금흐름표',
  '결산부속명세서',
  '기간비용 현황',
];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

// 가정: 전표 금액은 차변 - 대리 금액을 계정과목별로 합산하고 결산자료 금액을 더한다.
// 회계단위는 결산자료에만 있어 회계단위 조건은 결산자료에만 적용한다.
const TOTALS_CTE = `
  WITH amounts AS (
    SELECT l.account_subject_id AS account_subject_id,
           SUM(l.debit_amount - l.credit_amount) AS amount
      FROM journal_entry_line l
      JOIN journal_entry j ON j.journal_entry_id = l.journal_entry_id
     WHERE to_char(j.entry_date, 'YYYY-MM') BETWEEN :startPeriod AND :endPeriod
     GROUP BY l.account_subject_id
    UNION ALL
    SELECT c.account_subject_id AS account_subject_id,
           SUM(c.closing_amount) AS amount
      FROM closing_data c
     WHERE c.closing_period BETWEEN :startPeriod AND :endPeriod
       AND (CAST(:accountingUnitId AS bigint) IS NULL
            OR c.accounting_unit_id = CAST(:accountingUnitId AS bigint))
     GROUP BY c.account_subject_id
  ),
  totals AS (
    SELECT account_subject_id, SUM(amount) AS amount
      FROM amounts
     GROUP BY account_subject_id
  )
`;

@Controller('api/v1')
export class FnSfr01002Controller {
  @Get('/financial-statements')
  async listFinancialStatements(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const query = checks.queryOf(req.query);

    const statementType = String(query['statementType'] ?? '').trim();
    const startPeriod = String(query['startPeriod'] ?? '').trim();
    const endPeriod = String(query['endPeriod'] ?? '').trim();
    const unitText = String(query['accountingUnitId'] ?? '').trim();

    if (!statementType || !STATEMENT_TYPES.includes(statementType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '재무제표 종류를 선택해 주세요.');
    }
    if (!PERIOD_PATTERN.test(startPeriod)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작 회계기간을 YYYY-MM 형식으로 입력해 주세요.');
    }
    if (!PERIOD_PATTERN.test(endPeriod)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 종료 회계기간을 YYYY-MM 형식으로 입력해 주세요.');
    }
    if (unitText && !/^\d+$/.test(unitText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '회계단위가 올바르지 않습니다.');
    }
    // YYYY-MM 문자열은 사전순이 곧 시간순이다.
    if (startPeriod > endPeriod) {
      throw new ApiError(422, 'INVALID_PERIOD', '조회 시작 기간이 종료 기간보다 늦을 수 없습니다.');
    }

    const pageText = String(query['page'] ?? '0').trim() || '0';
    const sizeText = String(query['size'] ?? String(DEFAULT_SIZE)).trim() || String(DEFAULT_SIZE);
    const page = Number(pageText);
    let size = Number(sizeText);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }

    return transaction(async (db) => {
      const base = {
        startPeriod,
        endPeriod,
        accountingUnitId: unitText ? unitText : null,
      };
      const items = await db.query(
        `${TOTALS_CTE}
         SELECT a.account_subject_id AS "accountSubjectId",
                a.name AS "accountSubjectName",
                t.amount AS "amount"
           FROM totals t
           JOIN account_subject a ON a.account_subject_id = t.account_subject_id
          ORDER BY a.code
          LIMIT :size OFFSET :offset`,
        { ...base, size, offset: page * size },
      );
      const counts = await db.query(
        `${TOTALS_CTE}
         SELECT COUNT(*) AS "total"
           FROM totals t
           JOIN account_subject a ON a.account_subject_id = t.account_subject_id`,
        base,
      );
      const total = Number(counts[0]?.['total'] ?? 0);
      return { items, page, size, total };
    });
  }
}

