import { useState } from 'react';
import {
  Band,
  DataTable,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  Pager,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const STATEMENT_TYPES: [string, string][] = [
  ['합계잔액시산표', '합계잔액시산표'],
  ['원가보고서', '원가보고서'],
  ['손익계산서', '손익계산서'],
  ['이익잉여금처분계산서', '이익잉여금처분계산서'],
  ['재무상태표', '재무상태표'],
  ['자본변동표', '자본변동표'],
  ['현금흐름표', '현금흐름표'],
  ['결산부속명세서', '결산부속명세서'],
  ['기간비용 현황', '기간비용 현황'],
];

const EMPTY_PAGE: Page = { items: [], page: 0, size: 20, total: 0 };

export default function FnSfr01002Page({ role, notify }: PageProps) {
  const [statementType, setStatementType] = useState('');
  const [startPeriod, setStartPeriod] = useState('');
  const [endPeriod, setEndPeriod] = useState('');
  const [accountingUnitId, setAccountingUnitId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [formError, setFormError] = useState('');

  const { data, error, loading, reload } = useData<Page>(async () => {
    if (!applied) {
      return EMPTY_PAGE;
    }
    return call<Page>('GET', '/financial-statements', role, undefined, { ...applied, page: pageNo });
  }, [applied, pageNo, role]);

  const search = () => {
    if (!statementType || !startPeriod || !endPeriod) {
      setFormError('재무제표 종류와 조회 기간(시작·종료)을 모두 입력해 주세요.');
      return;
    }
    setFormError('');
    setPageNo(0);
    setApplied({ statementType, startPeriod, endPeriod, accountingUnitId });
    reload();
  };

  const reset = () => {
    setStatementType('');
    setStartPeriod('');
    setEndPeriod('');
    setAccountingUnitId('');
    setFormError('');
    setPageNo(0);
    setApplied(null);
  };

  const rows = data?.items ?? [];
  const emptyText = applied
    ? '조회 조건에 해당하는 데이터가 없습니다.'
    : '재무제표 종류와 기간을 선택한 뒤 조회해 주세요.';

  return (
    <div className="doc">
      <section className="box">
        <h2>주요 재무제표 조회</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="재무제표 종류" required>
            <Select value={statementType} onChange={setStatementType} options={STATEMENT_TYPES} />
          </Field>
          <Field label="조회 시작 회계기간" required hint="YYYY-MM">
            <TextInput value={startPeriod} onChange={setStartPeriod} placeholder="2024-01" />
          </Field>
          <Field label="조회 종료 회계기간" required hint="YYYY-MM">
            <TextInput value={endPeriod} onChange={setEndPeriod} placeholder="2024-12" />
          </Field>
          <Field label="회계단위">
            <LookupSelect
              table="accounting_unit"
              role={role}
              value={accountingUnitId}
              onChange={setAccountingUnitId}
            />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {error ? <ErrorText text={error} /> : null}
      </section>
      <section className="box">
        <h2>{applied ? `${String(applied.statementType)} 조회 결과` : '조회 결과'}</h2>
        <Band total={data?.total ?? 0} />
        <DataTable
          columns={[
            { key: 'accountSubjectName', label: '계정과목 명칭' },
            { key: 'amount', label: '계정과목별 금액', render: (row) => <Num value={row.amount} /> },
          ]}
          rows={loading ? [] : rows}
          empty={loading ? '불러오는 중입니다.' : emptyText}
        />
        <Pager
          page={data?.page ?? 0}
          size={data?.size ?? 20}
          total={data?.total ?? 0}
          onPage={setPageNo}
        />
      </section>
    </div>
  );
}
